		#region Events

		protected override RemoveAction GetRemoveActionOnDocketStatusOrFinalisedDateChange(WhsDocket docket)
		{
			var result = RemoveAction.RemoveAndDelete;

			if (docket != null && docket.IsFinalisedOrCancelled)
			{
				result = RemoveAction.NoRemovePossible;
			}

			return result;
		}

		protected override void OnDoubleClickDocketLine()
		{
			base.OnDoubleClickDocketLine();
			ShowOrderLineEditForm((WhsWorkOrderLine)LinesGrid.ListManager.List[LinesGrid.CurrentRowIndex]);
		}

		public void ShowOrderLineEditForm(WhsWorkOrderLine orderLine)
		{
			if (orderLine == null)
			{
				Globals.Message.ShowWarning(Res.GetString("e1ea3cc6-b109-499f-8a2a-6cb353366450", "Please select an order line to edit"));
			}
			else if (orderLine.HasChanges)
			{
				Globals.Message.ShowWarning(Res.GetString("d7daab7a-3e5f-4445-b804-eca8e4a86070", "Please save this Order before going to the Order Line Form"));
			}
			else
			{
				var controller = ZControllerFactory.Create(ControllerIDs.WhsWorkOrderLine);
				controller.SetFormsModalTo(this.FindForm());
				controller.ShowEditForm(orderLine);
			}
		}

		#endregion

		#region Docket, Selected Lines

		public new WhsWorkOrder Docket => (WhsWorkOrder)base.Docket;

		public WhsWorkOrderLine[] GetSelectedLines()
		{
			return Array.ConvertAll(LinesGrid.SelectedElements, bizO => (WhsWorkOrderLine)bizO);
		}

		#endregion

		#region Context Menu

		void ContextMenu_Popup(object sender, EventArgs e)
		{
			UpdateBOMMenuItemState();
			UpdateDuplicateMenuItemState();
		}

		void UpdateBOMMenuItemState()
		{
			foreach (MenuItem item in LinesGrid.ContextMenu.MenuItems)
			{
				var bomItem = item as BOMMenuItem;
				if (bomItem != null)
				{
					bomItem.UpdateCheckedAndEnabledStateForSelectedLines(GetSelectedLines());
					break;
				}
			}
		}

		void UpdateDuplicateMenuItemState()
		{
			var duplicateItem = LinesGrid.ContextMenu.MenuItems.Find("Duplicate", false); // SuppressCodeSmell Reason = Menu Item key
			if (duplicateItem.Length == 0)
			{
				throw new NotSupportedException("Context menu does not have a 'Duplicate' menu item.");
			}
			else if (duplicateItem.Length > 1)
			{
				throw new NotSupportedException("Multiple menu items were found with the key 'Duplicate'.");
			}

			duplicateItem[0].Enabled = IsAllSelectedLinesBOMTopLevelProduct;
		}

		bool IsAllSelectedLinesBOMTopLevelProduct
		{
			get
			{
				var selectedLines = GetSelectedLines();
				return selectedLines.Length > 0 && !selectedLines.Any(line => !line.BOM.IsTopLevelProduct);
			}
		}

